<?php
declare(strict_types=1);
final class RiskService {public function calculate(array $i):array{$capital=sf($i['capital']??0);$rp=sf($i['risk_percent']??0);$entry=sf($i['entry']??0);$stop=sf($i['stop']??0);$target=sf($i['target']??0);$side=($i['side']??'long')==='short'?'short':'long';$lev=max(1,min(100,sf($i['leverage']??1)));$cost=max(0,min(5,sf($i['cost_percent']??0)));if(min($capital,$entry,$stop,$target)<=0)throw new InvalidArgumentException('Capital, entry, stop and target must be positive.');if($rp<=0||$rp>MAX_RISK_PERCENT)throw new InvalidArgumentException('Risk must be above zero and not exceed MAX_RISK_PERCENT ('.MAX_RISK_PERCENT.'%).');if(($side==='long'&&!($stop<$entry&&$target>$entry))||($side==='short'&&!($target<$entry&&$stop>$entry)))throw new InvalidArgumentException('Long: stop below entry and target above. Short: target below entry and stop above.');$dist=abs($entry-$stop)/$entry;$td=abs($target-$entry)/$entry;$risk=$capital*$rp/100;$notional=$risk/$dist;$fees=$notional*$cost/100;$gross=$notional*$td;$net=$gross-$fees;return ['capital'=>$capital,'riskPercent'=>$rp,'riskAmount'=>round($risk,2),'entry'=>$entry,'stop'=>$stop,'target'=>$target,'side'=>$side,'leverage'=>$lev,'priceRiskPercent'=>round($dist*100,4),'targetMovePercent'=>round($td*100,4),'notionalEstimate'=>round($notional,2),'marginEstimate'=>round($notional/$lev,2),'grossTargetEstimate'=>round($gross,2),'estimatedCosts'=>round($fees,2),'netTargetEstimate'=>round($net,2),'stopLossEstimate'=>round($risk+$fees,2),'rewardRisk'=>round($net/max($risk,0.000001),2),'warning'=>'Linear estimate only. Verify contract multiplier, settlement currency, fees, funding, slippage, minimum size and margin rules. Not exchange-exact P&L.'];}}
